import {seedCopy,seedFamilies,makeSeedSource,seedQuantity} from './seed-exchange-content.mjs';
import * as core from './seed-exchange-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,disabled=false)=>`<button type='button' data-seed-action='${action}'${disabled?' disabled':''}>${esc(label)}</button>`;
const p=(text,cls='')=>`<p class='${cls}' data-seed-read>${esc(text)}</p>`;
export function seedExchangeEntry(){return `<aside class='seed-entry'><h2>The seed exchange table</h2><p>The orchard keeper needs a clear card for the courier. Build a trade, or share the seedlings.</p><a href='#desk/exchange'>Open the exchange table</a></aside>`;}
function icon(kind){return kind==='baskets'?`<svg viewBox='0 0 40 40' aria-hidden='true'><path d='M9 18Q20 0 31 18M5 18H35L31 35H9ZM10 24H31M11 29H30M15 19L17 34M24 19L23 34'/></svg>`:`<svg viewBox='0 0 40 40' aria-hidden='true'><path d='M11 36L15 4M20 36V2M29 36L25 5M11 20L29 22L28 27L12 25ZM14 12L8 8M20 10L26 3M26 14L32 9'/></svg>`;}
function tradePicture(s){const apples=s.family==='apples',send=apples?'baskets':'bundles',receive=apples?'bundles':'baskets',cost=apples?s.basketRate:s.reedRate,gain=apples?s.reedRate:s.basketRate;return `<figure class='seed-trade'><div class='seed-goods' aria-hidden='true'>${Array.from({length:cost},()=>icon(send)).join('')}</div><span class='seed-arrow' aria-hidden='true'>⇄</span><div class='seed-goods' aria-hidden='true'>${Array.from({length:gain},()=>icon(receive)).join('')}</div><figcaption data-seed-read>One whole trade group: ${esc(seedQuantity(cost,send))} for ${esc(seedQuantity(gain,receive))}.</figcaption></figure>`;}
function nurseryPicture(s,value){return `<figure class='seed-nursery'>${s.parts.map((count,i)=>`<div class='seed-town'><h3>${esc(s.labels.towns[i])} · ${count} ${count===1?'part':'parts'}</h3><div class='seed-parts'>${Array.from({length:count},()=>`<div class='seed-part'><span aria-hidden='true' class='seed-dots'>${Array.from({length:value},()=>'<i></i>').join('')}</span><strong>${value}</strong><span> ${value===1?'seedling':'seedlings'}</span></div>`).join('')}</div></div>`).join('')}<figcaption data-seed-read>Each box is one equal part. Every part holds ${esc(seedQuantity(value,'seedlings'))}.</figcaption></figure>`;}
function courierList(s,d){return `<ul>${core.seedCourierList(s,d).map(x=>`<li>${esc(x.label)}: ${esc(seedQuantity(x.value,x.unit))}</li>`).join('')}</ul>`;}
function material(s,draft,example=false){const m=core.seedModel(s,draft);if(!m)return p('This saved model cannot be read here.');const nursery=s.family==='nursery',value=nursery?m.value:m.groups;
 return `${nursery?nurseryPicture(s,value):tradePicture(s)}${!example?`<div class='seed-build'><span class='seed-count' data-seed-read>${value} ${nursery?'seedlings in every part':value===1?'whole trade group':'whole trade groups'}</span><div>${button('less',nursery?'One fewer in each part':'Lift one group',value===0)}${button('more',nursery?'One more in each part':'Add one group',value===12)}</div></div>`:''}<dl class='seed-totals' data-seed-read>${core.seedCourierList(s,draft).map(x=>`<div><dt>${esc(x.label)}</dt><dd>${esc(seedQuantity(x.value,x.unit))}</dd></div>`).join('')}</dl>${!nursery?`<div class='seed-stamps' aria-hidden='true'>${Array.from({length:12},(_,i)=>`<span${i<value?` class='chosen'`:''}>${i+1}</span>`).join('')}</div>`:''}`;
}
function snapshot(k,label){if(!core.validSeedSnapshot(k))return `<section><h3>${label}</h3><p>This version is retained unchanged but cannot be read here. Download Notes to preserve it.</p></section>`;return `<section class='seed-kept'><h3>${label}</h3><p>${k.status==='fits'?'Checked fit when kept':'Still working when kept'}</p><ul>${k.list.map(x=>`<li>${esc(x.label)}: ${esc(seedQuantity(x.value,x.unit))}</li>`).join('')}</ul><p class='seed-original'>${esc(k.ownNote)}</p><p>${k.checks.length} ${k.checks.length===1?'check':'checks'} kept with this version.</p></section>`;}
let views=new WeakMap();
function local(state,owner){let v=views.get(state);const id=state.seedExchange?.currentId||'';if(!v||v.owner!==owner||v.id!==id){const family=core.seedExchangeView(state).work?.source.family||'apples';v={owner,id,example:false,family,size:core.seedSuggestion(state,family).size};views.set(state,v);}return v;}
function chooser(view,state,v){return `<details data-seed-panel='choose'><summary>Another card and earlier work</summary><label>Choose a job<select data-seed-family>${seedFamilies.map(f=>`<option value='${f}'${v.family===f?' selected':''}>${esc(seedCopy.families[f])}</option>`).join('')}</select></label><label>Groups or seedlings in each part<select data-seed-size>${Array.from({length:12},(_,n)=>`<option value='${n+1}'${v.size===n+1?' selected':''}>${n+1}</option>`).join('')}</select></label>${button('start',view.work?'Another card':'Start this card',!view.canCreate)}<p>Choose any card. Earlier cards stay in your notes. A familiar card can come round again.</p>${view.reason?p(errors[view.reason]||errors.unavailable):''}${view.visits.length?`<h3>Earlier cards</h3><div class='seed-history'>${view.visits.map(x=>x.readable?`<button type='button' data-seed-open='${esc(x.id)}' aria-pressed='${x.id===state.seedExchange?.currentId}'>${esc(x.id)} · ${esc(x.source.title)}</button>`:`<p>${esc(x.id)} is kept unchanged but cannot be read here.</p>`).join('')}</div><label>Card to remove<select data-seed-remove><option value=''>Choose one card</option>${view.visits.filter(x=>x.readable).map(x=>`<option value='${esc(x.id)}'>${esc(x.id)} · ${esc(x.source.title)}</option>`).join('')}</select></label>${button('remove','Remove selected card')}`:''}<a href='#notes'>Download your notes</a></details>`;}
export function seedExchangePage(state,owner=''){
 const view=core.seedExchangeView(state),v=local(state,owner),w=view.work,heading=`<header class='seed-heading'><div><a href='#desk'>← Keeper’s Desk</a><h1 id='seed-title' tabindex='-1'>The seed exchange table</h1></div><a href='#almanac/upstream-reply'>Upstream Post</a></header>`;
 if(view.status==='unsupported')return `<section class='seed-page' data-seed-root>${heading}<p>This saved format is kept unchanged. Other places in town are open.</p><a href='#notes'>Download your notes</a></section>`;
 const source=w?.source||makeSeedSource(state.seedExchange?.nextSerial||1,{family:v.family,size:v.size})||makeSeedSource(1);let body;
 if(!w)body=`${p(seedCopy.invitation)}${p(source.prompt)}${source.family==='nursery'?nurseryPicture(source,0):tradePicture(source)}<div class='seed-preview-start'>${button('start','Start this card',!view.canCreate)}${hearButton('','Hear this card')}</div>`;
 else if(v.example){const s={...w.source,...w.source.example},d=s.family==='nursery'?{partValue:s.size}:{groups:s.size};body=`<h2 id='seed-task' tabindex='-1'>A separate worked example</h2>${p('Your own card stays as you left it. These are different quantities.')}<ol>${s.steps.map(x=>`<li data-seed-read>${esc(x)}</li>`).join('')}</ol>${material(s,d,true)}${button('close-example','Return to my card')}${hearButton('','Hear this example')}`;}
 else body=`<h2 class='seed-task' id='seed-task' tabindex='-1'>${esc(source.title)}</h2>${p(source.prompt,'seed-request')}${p(source.rule,'seed-rule')}${material(source,w.draft)}<div class='seed-actions'>${button('check',source.family==='nursery'?'Check these parts':'Check these groups')}${button('keep','Keep this card')}${hearButton('','Hear this card')}</div>${core.seedReady(w)?p(source.family==='nursery'?'These parts fit this card.':'These groups fit this card.','seed-fit'):''}${view.familiar?p('A familiar card.'):''}${w.checks.length?`<aside class='seed-feedback' id='seed-feedback' tabindex='-1'>${p(w.checks.at(-1).feedback)}</aside>`:''}`;
 return `<section class='seed-page' data-seed-root>${heading}<div class='seed-table'>${body}</div><p class='seed-status' id='seed-status' role='status' aria-live='polite' tabindex='-1' data-seed-read></p>${p(source.notice,'seed-notice')}${w?`<details data-seed-panel='help'><summary>Help and another example</summary>${button('hint','Show a hint')}${button('example','Show another example')}${w.help.hint?`<aside id='seed-hint' tabindex='-1'>${p(source.hint)}</aside>`:''}</details><details data-seed-panel='note'><summary>Your courier note (optional)</summary>${p(seedCopy.note)}<h3>On this exchange card:</h3>${courierList(source,w.draft)}<p>${core.seedReady(w)?'The model was checked.':'Still working.'} Your own note is not automatically changed.</p><label>Your words<textarea data-seed-note maxlength='1200' rows='3'>\n${esc(w.ownNote)}</textarea></label>${button('keep','Keep this card')}${Object.hasOwn(w,'firstKept')?snapshot(w.firstKept,'First kept version'):''}${Object.hasOwn(w,'latestKept')?snapshot(w.latestKept,'Latest kept version'):''}</details>`:''}${chooser(view,state,v)}<details data-seed-panel='grownup'><summary>Grown-up practice notes</summary><p>${esc(seedCopy.grownup)}</p><p>Current suggestion: ${core.seedSuggestion(state,v.family).size}. ${esc(suggestionText(core.seedSuggestion(state,v.family).reason))}</p><a href='#notes'>Grown-up notes and downloads</a></details></section>`;
}
const suggestionText=code=>({new:'No retained first-check history for this job.',smaller:'The most recent distinct first construction used help or needed adjustment; try smaller quantities if useful.',more:'Three distinct retained first constructions fit without optional help; larger quantities are available.',same:'A few retained first checks inform this suggestion. It is not a level.'}[code]||'All choices remain open.');
const errors={unavailable:'This saved card is kept unchanged. Other readable cards and the rest of the town are open. Download your notes.',unexportable:'We could not keep this change. Your earlier work is still here.','visit-cap':'Twelve cards are retained. Download Notes, then remove one selected readable card to open another.',counter:'New cards are paused because the saved card counter needs attention. Earlier work remains available.',collision:'That card number is already used. Your earlier work is unchanged. Download your notes.','check-cap':'This card already has twenty-four checks. Keep or download it, then choose another card. Earlier checks stay here.','kept-unavailable':'An earlier kept version cannot be read here. Keep cannot replace it. Your current words and model stay here; download Notes.','note-length':'Keep the note within 1,200 characters, or download the visible words before changing them.',selection:'Choose one of the available jobs and quantities.',material:'Choose a construction from zero to twelve.',confirmation:'Confirm which card to remove.'};
export function seedExchangeNotes(state){if(!Object.hasOwn(state,'seedExchange'))return '';const v=core.seedExchangeView(state);let raw;try{raw=JSON.stringify(state.seedExchange,null,2);}catch{raw='Original data remains in the full notebook download.';}return `<details class='panel'><summary>Seed exchange: constructions and courier notes</summary><p>${esc(seedCopy.grownup)}</p>${v.visits.map(x=>`<section><h3>${esc(x.id)}</h3>${x.readable?`${p(x.source.title)}${Object.hasOwn(state.seedExchange.visits[x.id],'firstKept')?snapshot(state.seedExchange.visits[x.id].firstKept,'First kept version'):''}${Object.hasOwn(state.seedExchange.visits[x.id],'latestKept')?snapshot(state.seedExchange.visits[x.id].latestKept,'Latest kept version'):''}`:'<p>Earlier unreadable work stays unchanged in the download.</p>'}</section>`).join('')}<a href='#desk/exchange'>Return to the exchange table</a><details><summary>Full saved cards and source text</summary><pre>${esc(raw)}</pre></details></details>`;}

let controller,pendingNavigation=()=>false;
export function guardSeedExchangeNavigation(){return pendingNavigation();}
export function bindSeedExchange(state,ctx={}){
 controller?.abort();controller=new AbortController();pendingNavigation=()=>false;
 const root=document.querySelector('[data-seed-root]');if(!root)return;
 const owner=ctx.explorerId?.()??'',id=state.seedExchange?.currentId,route='#desk/exchange',v=local(state,owner);let ownedRoot=state.seedExchange,dirty=false;
 const owned=()=>root.isConnected&&document.querySelector('[data-seed-root]')===root&&(!ctx.notebook||ctx.notebook()===state)&&(ctx.explorerId?.()??'')===owner&&(!ctx.isActive||ctx.isActive())&&state.seedExchange===ownedRoot&&state.seedExchange?.currentId===id;
 const live=el=>owned()&&location.hash===route&&el.isConnected&&root.contains(el)&&!el.closest('details:not([open]),[hidden]')&&el.getClientRects().length>0&&!document.querySelector('dialog[open]');
 const status=(message,focus=false)=>{const n=root.querySelector('#seed-status');if(n){n.textContent=message;if(focus)n.focus({preventScroll:true});}};
 const persistence=()=>{const r=ctx.save?.();return r?.enabled===false?'Kept for this visit; browser saving is off. Download Notes to retain it.':r?.ok===false?'Kept in this tab, but browser saving failed. Download Notes before leaving.':r?.ok===true?'Saved on this device.':'Kept in this tab.';};
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 function redraw(message='',target='#seed-task'){
  const open=[...root.querySelectorAll('[data-seed-panel][open]')].map(d=>d.dataset.seedPanel);ctx.render?.();
  const next=document.querySelector('[data-seed-root]');if(!next||ctx.notebook&&ctx.notebook()!==state||(ctx.explorerId?.()??'')!==owner||location.hash!==route)return;
  for(const d of next.querySelectorAll('[data-seed-panel]'))d.open=open.includes(d.dataset.seedPanel);
  const s=next.querySelector('#seed-status');if(s)s.textContent=message;
  const focus=next.querySelector(target)||next.querySelector('#seed-title');if(focus&&!focus.closest('details:not([open])')){focus.focus({preventScroll:true});const b=focus.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)focus.scrollIntoView({block:'nearest'});}
 }
 function unsaved(){
  status('Your visible words could not be kept. They are still in the box. Edit to try again, download a draft copy, or restore the earlier words.');
  const s=root.querySelector('#seed-status'),download=document.createElement('button');download.type='button';download.textContent='Download visible draft';download.dataset.seedDraftDownload='';
  download.addEventListener('click',()=>{if(!live(download))return;const input=root.querySelector('[data-seed-note]');if(!input)return;const url=URL.createObjectURL(new Blob([input.value],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='courier-note-draft.txt';a.dataset.seedDraftLocal='';root.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  const restore=document.createElement('button');restore.type='button';restore.textContent='Restore earlier words';restore.addEventListener('click',()=>{if(!live(restore)||!window.confirm('Discard the visible words and restore the earlier note from this tab?'))return;dirty=false;stop();redraw('Earlier words restored.','[data-seed-note]');});s?.append(download,restore);
 }
 const options={canExport:ctx.canExport};
 function act(el,fn,message,target){if(!live(el))return;if(dirty){unsaved();return;}const result=fn();if(!result.ok){status(errors[result.error]||'This change was not kept.',true);return;}ownedRoot=state.seedExchange;stop();redraw(`${message} ${result.changed===false?'':persistence()}`,target);}
 root.querySelectorAll('[data-seed-action]').forEach(el=>el.addEventListener('click',()=>{
  if(!live(el))return;const action=el.dataset.seedAction,w=core.seedExchangeView(state).work;
  if(action==='start')return act(el,()=>core.startSeedExchange(state,{family:v.family,size:v.size},options),'A new card is open. Earlier cards are retained.');
  if(action==='more'||action==='less'){if(!w||v.example)return;const value=w.source.family==='nursery'?w.draft.partValue:w.draft.groups;return act(el,()=>core.setSeedMaterial(state,value+(action==='more'?1:-1),options),'Construction changed.',`[data-seed-action='${action}']:not([disabled])`);}
  if(action==='check'&&!v.example)return act(el,()=>core.checkSeedExchange(state,options),'Check kept. You can adjust the model.','#seed-feedback');
  if(action==='keep')return act(el,()=>core.keepSeedExchange(state,options),'Card kept. Its first version is still here.');
  if(action==='hint')return act(el,()=>core.showSeedHelp(state,'hint',options),'Hint shown.','#seed-hint');
  if(action==='example'){if(dirty){unsaved();return;}const r=core.showSeedHelp(state,'example',options);if(!r.ok){status(errors[r.error]||'The example could not be opened.',true);return;}ownedRoot=state.seedExchange;v.example=true;stop();redraw(`A separate example. ${r.changed===false?'':persistence()}`);return;}
  if(action==='close-example'){if(dirty){unsaved();return;}v.example=false;stop();redraw('Your card is unchanged.');return;}
  if(action==='remove'){if(dirty){unsaved();return;}const key=root.querySelector('[data-seed-remove]')?.value,chosen=state.seedExchange?.visits?.[key];if(!core.validSeedWork(chosen)){status('Choose one readable card to remove.',true);return;}if(!window.confirm(`Remove ${key}, its checks, note and kept versions? Download Notes first to keep a copy.`))return;return act(el,()=>core.removeSeedExchange(state,key,true,options),'Only the selected card was removed.','#seed-title');}
 }));
 root.querySelectorAll('[data-seed-open]').forEach(el=>el.addEventListener('click',()=>act(el,()=>core.openSeedExchange(state,el.dataset.seedOpen,options),'Earlier card opened.')));
 const input=root.querySelector('[data-seed-note]');input?.addEventListener('input',()=>{if(!live(input))return;const r=core.setSeedNote(state,input.value,options);if(r.ok){ownedRoot=state.seedExchange;dirty=false;input.removeAttribute('aria-invalid');status(persistence());}else{dirty=true;input.setAttribute('aria-invalid','true');unsaved();}});
 for(const [selector,key]of [['[data-seed-family]','family'],['[data-seed-size]','size']]){const select=root.querySelector(selector);select?.addEventListener('change',()=>{if(!live(select))return;if(dirty){select.value=String(v[key]);unsaved();return;}v[key]=key==='size'?Number(select.value):select.value;if(key==='family')v.size=core.seedSuggestion(state,v.family).size;stop();redraw('',selector);});}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b))return;if(!live(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-seed-read]')].filter(n=>!n.closest('details:not([open]),[hidden]')&&n.getClientRects().length>0).map(n=>n.textContent.trim()).join(' ');},{capture:true});
 root.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{if(!live(a)){e.preventDefault();return;}if(dirty){e.preventDefault();unsaved();}else stop();}));
 document.addEventListener('click',e=>{if(!dirty||!owned())return;const control=e.target.closest?.('button,a,input,select');if(!control||root.contains(control)&&(!control.matches('a')||control.matches('[data-seed-draft-local]')))return;e.preventDefault();e.stopImmediatePropagation();unsaved();},{capture:true,signal:controller.signal});
 pendingNavigation=()=>{if(!dirty||!owned()||location.hash===route)return false;history.replaceState(null,'',route);unsaved();return true;};
 window.addEventListener('beforeunload',e=>{if(dirty&&owned()){e.preventDefault();e.returnValue='';}},{signal:controller.signal});
}
